Évalue chaque paire question/SQL pour ce schéma SQLite.

Question à te poser : un expert SQL qui lit seulement la question française et le schéma écrirait-il une requête dont le résultat est identique à celui du SQL fourni ?

- pass : oui. La question peut être formulée naturellement, sans nommer les colonnes techniques ni décrire la syntaxe ; les choix conventionnels d'un expert (par exemple afficher le nom pour « quel client ») sont acceptables.
- fail : la question ajoute, retire ou modifie une contrainte ; le SQL renvoie des colonnes que la question ne demande pas, ou oublie une colonne demandée ; l'agrégat, le tri, la limite, la négation, la jointure ou une valeur ne correspond pas ; la question est absurde, tautologique ou mal écrite en français.
- uncertain : la question admet plusieurs lectures raisonnables qui donnent des résultats différents.

Conventions du jeu Spider, à accepter sans les pénaliser : jointure interne même pour « chaque » ou « tous » ; regroupement ou INTERSECT/EXCEPT sur un nom affiché plutôt que sur un identifiant ; doublons possibles sans DISTINCT quand la question ne demande pas explicitement des valeurs distinctes ; cas limites théoriques (homonymes, valeurs NULL, ex æquo) que la question n'évoque pas. Ne rejette que les écarts de sens réels.

Retourne exactement un verdict pour chaque identifiant fourni ; dans issues, décris brièvement le problème (liste vide si pass).

{"schema": "CREATE INDEX idx_receipts_method ON receipts(payment_method);

CREATE INDEX idx_ticket_lines_ticket ON ticket_lines(ticket_id);

CREATE INDEX idx_tickets_site_date ON service_tickets(site_id, opened_at);

CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL, loyalty_level TEXT NOT NULL, joined_on TEXT NOT NULL);

CREATE TABLE offerings (offering_id INTEGER PRIMARY KEY, offering_name TEXT NOT NULL, category TEXT NOT NULL, unit_price REAL NOT NULL, vegetarian INTEGER NOT NULL, active INTEGER NOT NULL);

CREATE TABLE receipts (receipt_id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL, issued_at TEXT NOT NULL, payment_method TEXT NOT NULL, subtotal REAL NOT NULL, tip_amount REAL NOT NULL, paid_amount REAL NOT NULL, FOREIGN KEY (ticket_id) REFERENCES service_tickets(ticket_id));

CREATE TABLE service_sites (site_id INTEGER PRIMARY KEY, site_name TEXT NOT NULL, city TEXT NOT NULL, neighborhood TEXT NOT NULL, seating_capacity INTEGER NOT NULL, opening_year INTEGER NOT NULL);

CREATE TABLE service_tickets (ticket_id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL, customer_id INTEGER NOT NULL, opened_at TEXT NOT NULL, channel TEXT NOT NULL, status TEXT NOT NULL, table_code TEXT, FOREIGN KEY (site_id) REFERENCES service_sites(site_id), FOREIGN KEY (customer_id) REFERENCES customers(customer_id));

CREATE TABLE ticket_lines (line_id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL, offering_id INTEGER NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, FOREIGN KEY (ticket_id) REFERENCES service_tickets(ticket_id), FOREIGN KEY (offering_id) REFERENCES offerings(offering_id));", "examples": [{"id": "v2:new:synthetic_012:1:0", "question": "Quelle offre est proposée sur le ticket du site « Le Jardin Matinal » ?", "sql": "SELECT T1.offering_name FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id JOIN service_sites AS T4 ON T4.site_id = T3.site_id WHERE T1.offering_name = 'Espresso' AND T4.site_name = 'Le Jardin Matinal'"}, {"id": "v2:new:synthetic_012:1:1", "question": "Quel est le nom du client qui a commandé une boisson sur place au site « Le Jardin Matinal » ?", "sql": "SELECT T5.full_name FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id JOIN service_sites AS T4 ON T4.site_id = T3.site_id JOIN customers AS T5 ON T5.customer_id = T3.customer_id WHERE T1.offering_name = 'Espresso' AND T4.site_name = 'Le Jardin Matinal'"}, {"id": "v2:new:synthetic_012:1:2", "question": "Quels sont les sites où un espresso a été commandé ?", "sql": "SELECT DISTINCT T3.site_id FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id WHERE T1.offering_name = 'Espresso'"}, {"id": "v2:new:synthetic_012:1:4", "question": "Quels sont les noms des offres commandées par Alice Martin ?", "sql": "SELECT T4.offering_name FROM service_sites AS T1 JOIN service_tickets AS T2 ON T1.site_id = T2.site_id JOIN ticket_lines AS T3 ON T3.ticket_id = T2.ticket_id JOIN offerings AS T4 ON T4.offering_id = T3.offering_id JOIN customers AS T5 ON T5.customer_id = T2.customer_id WHERE T5.full_name = 'Alice Martin'"}, {"id": "v2:new:synthetic_012:1:5", "question": "Affichez tous les noms des clients et des sites de service.", "sql": "SELECT full_name FROM customers UNION SELECT site_name FROM service_sites"}, {"id": "v2:new:synthetic_012:1:6", "question": "Quelles offres coûtent plus cher que la boisson chaude la plus chère ?", "sql": "SELECT offering_name FROM offerings WHERE unit_price > (SELECT max(unit_price) FROM offerings WHERE category = 'boisson chaude')"}, {"id": "v2:new:synthetic_012:1:7", "question": "Quelles sont toutes les informations sur les lignes dont la quantité est comprise entre la quantité minimale et deux unités ?", "sql": "SELECT * FROM ticket_lines WHERE quantity BETWEEN (SELECT min(quantity) FROM ticket_lines) AND 2"}, {"id": "v2:new:synthetic_012:1:8", "question": "Quels sites ont à la fois un ticket sur place et un ticket payé ?", "sql": "SELECT T1.site_name FROM service_sites AS T1 JOIN service_tickets AS T2 ON T1.site_id = T2.site_id JOIN service_tickets AS T3 ON T3.site_id = T1.site_id WHERE T2.channel = 'sur_place' AND T3.status = 'paid'"}, {"id": "v2:new:synthetic_012:1:9", "question": "Quels identifiants d’offres ont un prix supérieur à 2 et inférieur à 5 ?", "sql": "SELECT offering_id FROM offerings WHERE unit_price > 2 INTERSECT SELECT offering_id FROM offerings WHERE unit_price < 5"}, {"id": "v2:new:synthetic_012:1:10", "question": "Quels sont, par ordre décroissant, le nombre de tickets et l’identifiant de chaque client ?", "sql": "SELECT COUNT(T3.receipt_id), T1.customer_id FROM customers AS T1 JOIN service_tickets AS T2 ON T1.customer_id = T2.customer_id JOIN receipts AS T3 ON T3.ticket_id = T2.ticket_id JOIN ticket_lines AS T4 ON T4.ticket_id = T2.ticket_id GROUP BY T1.customer_id ORDER BY COUNT(T3.receipt_id) DESC"}, {"id": "v2:new:synthetic_012:1:11", "question": "Quels sont l’identifiant, le nom et le nombre de lignes des sites ayant au moins deux lignes de commande ?", "sql": "SELECT T1.site_id, T1.site_name, count(*) FROM service_sites AS T1 JOIN service_tickets AS T2 ON T1.site_id = T2.site_id JOIN ticket_lines AS T3 ON T3.ticket_id = T2.ticket_id GROUP BY T1.site_id HAVING count(*) >= 2"}, {"id": "v2:new:synthetic_012:1:12", "question": "Quel est le nombre total de clients ayant ouvert un ticket à Paris ?", "sql": "SELECT count(*) FROM customers AS T1 JOIN service_tickets AS T2 ON T1.customer_id = T2.customer_id JOIN service_sites AS T3 ON T3.site_id = T2.site_id WHERE T3.city = 'Paris'"}, {"id": "v2:new:synthetic_012:1:13", "question": "Quel est le nom du client inscrit le plus récemment ?", "sql": "SELECT full_name FROM customers WHERE joined_on = (SELECT max(joined_on) FROM customers)"}, {"id": "v2:new:synthetic_012:1:15", "question": "Quel canal a enregistré le plus grand nombre de tickets ?", "sql": "SELECT channel FROM service_tickets GROUP BY channel ORDER BY count(*) DESC LIMIT 1"}, {"id": "v2:new:synthetic_012:2:0", "question": "Quels clients ont payé plus de 15 euros pour leur ticket ?", "sql": "SELECT T3.full_name FROM receipts AS T1 JOIN service_tickets AS T2 ON T1.ticket_id = T2.ticket_id JOIN customers AS T3 ON T2.customer_id = T3.customer_id WHERE T1.paid_amount > 15"}, {"id": "v2:new:synthetic_012:2:1", "question": "Combien d'offres différentes ont été commandées après le 8 janvier 2025 à 08 h 15 ?", "sql": "SELECT COUNT ( DISTINCT T3.offering_name ) FROM ticket_lines AS T1 JOIN service_tickets AS T2 ON T1.ticket_id = T2.ticket_id JOIN offerings AS T3 ON T1.offering_id = T3.offering_id WHERE T2.opened_at > '2025-01-08 08:15:00'"}, {"id": "v2:new:synthetic_012:2:2", "question": "Quel est le prix moyen des offres appartenant à la catégorie la moins représentée ?", "sql": "SELECT avg(unit_price) FROM offerings GROUP BY category ORDER BY count(*) ASC LIMIT 1"}, {"id": "v2:new:synthetic_012:2:3", "question": "Quel client a le plus grand nombre de tickets réglés par carte ?", "sql": "SELECT DISTINCT COUNT ( DISTINCT T2.ticket_id ), T1.full_name FROM receipts AS T3 JOIN service_tickets AS T2 ON T3.ticket_id = T2.ticket_id JOIN customers AS T1 ON T2.customer_id = T1.customer_id WHERE T3.payment_method = 'carte' GROUP BY T1.full_name ORDER BY COUNT ( DISTINCT T2.ticket_id ) DESC"}, {"id": "v2:new:synthetic_012:2:4", "question": "Quel est le numéro du ticket sur place qui contient un cappuccino ?", "sql": "SELECT T2.ticket_id FROM offerings AS T1 JOIN ticket_lines AS T3 ON T1.offering_id = T3.offering_id JOIN service_tickets AS T2 ON T3.ticket_id = T2.ticket_id WHERE T1.offering_name = 'Cappuccino' AND T2.channel = 'sur_place'"}, {"id": "v2:new:synthetic_012:3:0", "question": "Quel identifiant de ticket comprend l'offre « Espresso » ?", "sql": "SELECT DISTINCT T3.ticket_id FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id WHERE T1.offering_name = 'Espresso'"}, {"id": "v2:new:synthetic_012:3:1", "question": "Quels sont les identifiants des tickets qui contiennent un Espresso accompagné d'une autre offre ?", "sql": "SELECT DISTINCT T3.ticket_id FROM ticket_lines AS T3 JOIN offerings AS T2 ON T3.offering_id = T2.offering_id JOIN ticket_lines AS T4 ON T4.ticket_id = T3.ticket_id JOIN offerings AS T1 ON T4.offering_id = T1.offering_id WHERE T2.offering_name = 'Espresso' AND T1.offering_id != T2.offering_id"}, {"id": "v2:new:synthetic_012:3:2", "question": "Combien de tickets comprennent au moins une boisson chaude ?", "sql": "SELECT DISTINCT COUNT ( DISTINCT T3.ticket_id ) FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id WHERE T1.category = 'boisson chaude'"}, {"id": "v2:new:synthetic_012:3:3", "question": "Quel est le nom du site qui a enregistré le plus grand nombre de tickets ?", "sql": "SELECT T1.site_name FROM service_sites AS T1 JOIN service_tickets AS T2 ON T1.site_id = T2.site_id GROUP BY T1.site_id ORDER BY COUNT(*) DESC LIMIT 1"}, {"id": "v2:new:synthetic_012:3:4", "question": "Donne-moi le nombre de tickets qui contiennent l'offre « Espresso ».", "sql": "SELECT COUNT ( DISTINCT T3.ticket_id ) FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id WHERE T1.offering_name = 'Espresso'"}, {"id": "v2:new:synthetic_012:3:5", "question": "Combien d'offres différentes ont été commandées par Alice Martin entre le 1er et le 10 janvier 2025 ?", "sql": "SELECT COUNT ( DISTINCT T4.offering_name ) FROM customers AS T1 JOIN service_tickets AS T2 ON T1.customer_id = T2.customer_id JOIN ticket_lines AS T3 ON T2.ticket_id = T3.ticket_id JOIN offerings AS T4 ON T4.offering_id = T3.offering_id JOIN receipts AS T5 ON T2.ticket_id = T5.ticket_id WHERE T1.full_name = 'Alice Martin' AND T5.issued_at < '2025-01-10 00:00:00' AND T5.issued_at > '2025-01-01 00:00:00'"}, {"id": "v2:new:synthetic_012:3:6", "question": "Quel est le nom du client qui a commandé la plus grande quantité d'une même offre ?", "sql": "SELECT T1.full_name FROM customers AS T1 JOIN service_tickets AS T2 ON T1.customer_id = T2.customer_id JOIN ticket_lines AS T3 ON T2.ticket_id = T3.ticket_id WHERE T3.quantity = (SELECT MAX(quantity) FROM ticket_lines)"}, {"id": "v2:new:synthetic_012:3:8", "question": "Quels sont les identifiants des clients ayant eu un ticket payé sur place, mais pas via mobile ?", "sql": "SELECT customer_id FROM service_tickets WHERE status = 'paid' AND channel = 'sur_place' EXCEPT SELECT customer_id FROM service_tickets WHERE channel = 'mobile' AND status = 'paid'"}, {"id": "v2:new:synthetic_012:3:10", "question": "Où trouver à Paris, dans le quartier de Montparnasse, une offre chaude coûtant plus de 2 euros ?", "sql": "SELECT T3.table_code, T1.offering_name FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id JOIN service_sites AS T4 ON T3.site_id = T4.site_id WHERE T4.city = 'Paris' AND T4.neighborhood = 'Montparnasse' AND T1.category = 'boisson chaude' AND T1.unit_price > 2.0"}, {"id": "v2:new:synthetic_012:3:11", "question": "Combien de clients ont eu à la fois un ticket sur place et un ticket payé ?", "sql": "SELECT COUNT ( customer_id ) FROM service_tickets WHERE customer_id IN (SELECT customer_id FROM service_tickets WHERE channel = 'sur_place') AND status = 'paid'"}, {"id": "v2:new:synthetic_012:3:13", "question": "Quels sont les identifiants et les montants payés des 3 tickets les plus chers ?", "sql": "SELECT T2.ticket_id, T1.paid_amount FROM receipts AS T1 JOIN service_tickets AS T2 ON T1.ticket_id = T2.ticket_id ORDER BY T1.paid_amount DESC LIMIT 3"}, {"id": "v2:new:synthetic_012:3:14", "question": "Quel code de table et quelle offre chaude peut-on trouver sur un site de Lyon pour plus de 2,5 euros ?", "sql": "SELECT T3.table_code, T1.offering_name FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T3.ticket_id = T2.ticket_id JOIN service_sites AS T4 ON T3.site_id = T4.site_id WHERE T4.city = 'Lyon' AND T1.category = 'boisson chaude' AND T1.unit_price > 2.5"}, {"id": "v2:new:synthetic_012:3:15", "question": "Quel niveau de fidélité est le plus représenté parmi les clients ?", "sql": "SELECT loyalty_level FROM customers GROUP BY loyalty_level ORDER BY COUNT(*) DESC LIMIT 1"}, {"id": "v2:new:synthetic_012:4:0", "question": "Quelles offres ont été commandées lors de tickets réglés ?", "sql": "SELECT T1.offering_name FROM offerings AS T1 JOIN ticket_lines AS T2 ON T1.offering_id = T2.offering_id JOIN service_tickets AS T3 ON T2.ticket_id = T3.ticket_id WHERE T3.status = 'paid'"}, {"id": "v2:new:synthetic_012:4:1", "question": "Trouvez la date d'émission du reçu associé à la cliente Alice Martin lors d'un achat sur place.", "sql": "SELECT T3.issued_at FROM customers AS T1 JOIN service_tickets AS T2 ON T1.customer_id = T2.customer_id JOIN receipts AS T3 ON T2.ticket_id = T3.ticket_id WHERE T1.full_name = 'Alice Martin' AND T2.channel = 'sur_place'"}, {"id": "v2:new:synthetic_012:4:2", "question": "Quelle ville accueille le plus de sites de service ?", "sql": "SELECT city FROM service_sites GROUP BY city ORDER BY count(*) DESC LIMIT 1"}, {"id": "v2:new:synthetic_012:4:3", "question": "Quel est le nom et la ville du site fréquenté par la cliente Alice Martin ?", "sql": "SELECT DISTINCT T1.site_name, T1.city FROM service_sites AS T1 JOIN service_tickets AS T2 ON T1.site_id = T2.site_id JOIN customers AS T3 ON T2.customer_id = T3.customer_id WHERE T3.full_name = 'Alice Martin' AND T3.email = 'alice.martin@example.test'"}, {"id": "v2:new:synthetic_012:4:4", "question": "Quel site a encaissé le montant total le plus élevé ?", "sql": "SELECT T1.site_name FROM service_sites AS T1 JOIN service_tickets AS T2 ON T1.site_id = T2.site_id JOIN receipts AS T3 ON T2.ticket_id = T3.ticket_id GROUP BY T1.site_name ORDER BY sum(T3.paid_amount) DESC LIMIT 1"}, {"id": "v2:new:synthetic_012:4:5", "question": "Quelle catégorie d'offres compte le moins de lignes de commande ?", "sql": "SELECT T2.category FROM ticket_lines AS T1 JOIN offerings AS T2 ON T1.offering_id = T2.offering_id GROUP BY T1.offering_id ORDER BY count(*) LIMIT 1"}, {"id": "v2:new:synthetic_012:4:6", "question": "Quelles offres ont un prix unitaire supérieur au prix moyen de toutes les offres ?", "sql": "SELECT offering_name FROM offerings WHERE unit_price > (SELECT avg(unit_price) FROM offerings)"}, {"id": "v2:new:synthetic_012:4:7", "question": "Affichez les noms des offres et les dates d'ouverture des tickets correspondants, par ordre chronologique.", "sql": "SELECT T1.offering_name, T2.opened_at FROM offerings AS T1 JOIN ticket_lines AS T3 ON T1.offering_id = T3.offering_id JOIN service_tickets AS T2 ON T3.ticket_id = T2.ticket_id ORDER BY T2.opened_at ASC"}]}

