HERE T4.sport_name = 'Basketball' GROUP BY T3.coach_id ORDER BY COUNT(T1.session_id) DESC"}, {"id": "v2:new:synthetic_063:1:5", "question": "Donnez l'identifiant du sport, son nom et le nombre d'équipes correspondantes pour chaque sport, par nombre d'équipes croissant.", "sql": "SELECT T1.sport_id, T2.sport_name, COUNT(*) FROM team AS T1 JOIN sport AS T2 ON T1.sport_id = T2.sport_id GROUP BY T1.sport_id ORDER BY COUNT(*) ASC"}, {"id": "v2:new:synthetic_063:1:7", "question": "Quels sont le prénom et le nom des membres nés avant l'année de naissance moyenne ?", "sql": "SELECT first_name, last_name FROM member WHERE birth_year < (SELECT avg(birth_year) FROM member)"}, {"id": "v2:new:synthetic_063:1:9", "question": "Quel quartier compte le plus grand nombre de sites sportifs ?", "sql": "SELECT neighborhood FROM facility GROUP BY neighborhood ORDER BY count(*) DESC LIMIT 1"}, {"id": "v2:new:synthetic_063:1:10", "question": "Trouvez le prénom et le nom des entraîneurs qui ont encadré des séances au « Gymnase Central » mais pas à la « Salle Horizon ».", "sql": "SELECT T2.first_name, T2.last_name FROM training_session AS T1 JOIN facility AS T3 ON T1.facility_id = T3.facility_id JOIN coach AS T2 ON T1.coach_id = T2.coach_id WHERE T3.facility_name = 'Gymnase Central' EXCEPT SELECT T2.first_name, T2.last_name FROM training_session AS T1 JOIN facility AS T3 ON T1.facility_id = T3.facility_id JOIN coach AS T2 ON T1.coach_id = T2.coach_id WHERE T3.facility_name = 'Salle Horizon'"}, {"id": "v2:new:synthetic_063:1:11", "question": "Affichez le prénom des entraîneurs et le nom de leurs équipes, par ordre alphabétique croissant du prénom.", "sql": "SELECT T2.first_name, T3.team_name FROM training_session AS T1 JOIN coach AS T2 ON T1.coach_id = T2.coach_id JOIN team AS T3 ON T1.team_id = T3.team_id ORDER BY T2.first_name ASC"}, {"id": "v2:new:synthetic_063:1:12", "question": "Quel est le site sportif ayant la plus petite capacité ?", "sql": "SELECT facility_name FROM facility WHERE capacity = (SELECT MIN(capacity) FROM facility)"}, {"id": "v2:new:synthetic_063:1:13", "question": "Retournez les entraîneurs qui encadrent au moins une séance.", "sql": "SELECT T2.first_name FROM training_session AS T1 JOIN coach AS T2 ON T1.coach_id = T2.coach_id GROUP BY T2.first_name HAVING COUNT(DISTINCT T1.session_id) > 0"}, {"id": "v2:new:synthetic_063:1:14", "question": "Quelle équipe organise le plus grand nombre de séances ?", "sql": "SELECT T2.team_name FROM training_session AS T1 JOIN team AS T2 ON T1.team_id = T2.team_id GROUP BY T2.team_name ORDER BY count(*) DESC LIMIT 1"}, {"id": "v2:new:synthetic_063:1:15", "question": "Quelles sont les dernières séances de basketball ?", "sql": "SELECT DISTINCT T3.session_id, T3.session_date FROM sport AS T1 JOIN team AS T2 ON T1.sport_id = T2.sport_id JOIN training_session AS T3 ON T3.team_id = T2.team_id WHERE T1.sport_name = 'Basketball' ORDER BY T3.session_date DESC"}, {"id": "v2:new:synthetic_063:2:0", "question": "Quels sont le prénom et le nom du coach le plus ancien des équipes de basketball ?", "sql": "SELECT T3.first_name, T3.last_name FROM team AS T1 JOIN sport AS T2 ON T1.sport_id = T2.sport_id JOIN coach AS T3 ON T1.coach_id = T3.coach_id WHERE T2.sport_name = 'Basketball' AND T3.hire_year = ( SELECT MIN ( T3.hire_year ) FROM team AS T1 JOIN sport AS T2 ON T1.sport_id = T2.sport_id JOIN coach AS T3 ON T1.coach_id = T3.coach_id WHERE T2.sport_name = 'Basketball' )"}, {"id": "v2:new:synthetic_063:2:1", "question": "Quels membres sont inscrits à une séance des Aigles Centre, mais à aucune séance des Filets Nord ?", "sql": "SELECT T2.member_id FROM training_session AS T1 JOIN session_registration AS T2 ON T1.session_id = T2.session_id JOIN team AS T3 ON T1.team_id = T3.team_id WHERE T3.team_name = 'Aigles Centre' EXCEPT SELECT T2.member_id FROM training_session AS T1 JOIN session_registration AS T2 ON T1.session_id = T2.session_id JOIN team AS T3 ON T1.team_id = T3.team_id WHERE T3.team_name = 'Filets Nord'"