elles installations Claire Martin a-t-elle animé des séances ?", "sql": "SELECT T3.facility_name FROM coach AS T1 JOIN training_session AS T2 ON T1.coach_id = T2.coach_id JOIN facility AS T3 ON T2.facility_id = T3.facility_id WHERE T1.first_name = 'Claire' AND T1.last_name = 'Martin'"}, {"id": "v2:new:synthetic_063:5:15", "question": "Quelle installation du quartier Nord possède la plus grande capacité ?", "sql": "SELECT facility_name FROM facility WHERE capacity = ( SELECT MAX ( capacity ) FROM facility WHERE neighborhood = 'Nord' ) AND neighborhood = 'Nord'"}]}

