v2:new:synthetic_073:5:14", "question": "Combien de clients distincts de Nantes ont commandé des plantes vivaces ?", "sql": "SELECT COUNT ( DISTINCT T1.customer_name ) FROM customer AS T1 JOIN sales_order AS T2 ON T1.customer_id = T2.customer_id JOIN sales_order_line AS T3 ON T2.order_id = T3.order_id JOIN plant_variety AS T4 ON T3.variety_id = T4.variety_id WHERE T1.city = 'Nantes' AND T4.plant_type = 'vivace'"}, {"id": "v2:new:synthetic_073:5:15", "question": "Donnez chaque région des fournisseurs avec le nombre de lots correspondants, dans l'ordre croissant du nombre de lots.", "sql": "SELECT region, COUNT(*) FROM supplier AS T1 JOIN stock_lot AS T2 ON T1.supplier_id = T2.supplier_id GROUP BY region ORDER BY COUNT(*) ASC"}]}

